/* SiteStack service worker — generated by build.mjs */
const CACHE = 'sitestack-634c3d236efd';
const SHELL = ['./', './index.html', './manifest.webmanifest', './icon-192.png', './icon-512.png', './icon-maskable-512.png', './aps-callback.html'];
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(SHELL.map(u => new Request(u, { cache: 'reload' })))));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(ks => Promise.all(ks.filter(k => k.startsWith('sitestack-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener('message', e => { if (e.data === 'skipWaiting') self.skipWaiting(); });
self.addEventListener('fetch', e => {
  const r = e.request;
  if (r.method !== 'GET' || new URL(r.url).origin !== location.origin) return;
  // cache-first: the whole app is one versioned document; updates arrive as a new sw.js.
  // Only the app's own URL maps to index.html — other pages (aps-callback.html) are served as themselves
  const scope = new URL(self.registration.scope);
  if (r.mode === 'navigate' && (new URL(r.url).pathname === scope.pathname || new URL(r.url).pathname === scope.pathname + 'index.html')) {
    e.respondWith(caches.match('./index.html').then(c => c || fetch(r)));
    return;
  }
  e.respondWith(caches.match(r, { ignoreSearch: true }).then(c => c || fetch(r)));
});
